-- ============ Part 2: rules, security (hand-written) ============

ALTER TABLE document_folders
  ADD CONSTRAINT document_folders_name_check CHECK (length(btrim(name)) BETWEEN 1 AND 120 AND name !~ '[/\\]');
CREATE UNIQUE INDEX document_folders_unique_name ON document_folders (org_id, COALESCE(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(name));

ALTER TABLE contracts
  ADD CONSTRAINT contracts_status_check CHECK (status IN ('DRAFT', 'ACTIVE', 'EXPIRED', 'TERMINATED')),
  ADD CONSTRAINT contracts_dates_check CHECK (end_date IS NULL OR end_date >= start_date),
  ADD CONSTRAINT contracts_notice_check CHECK (renewal_notice_days BETWEEN 0 AND 365);

ALTER TABLE documents
  ADD CONSTRAINT documents_category_check CHECK (category IN ('CONTRACT', 'NDA', 'IDENTITY', 'TAX', 'INVOICE', 'POLICY', 'CERTIFICATE', 'OTHER')),
  ADD CONSTRAINT documents_confidentiality_check CHECK (confidentiality IN ('NORMAL', 'CONFIDENTIAL', 'RESTRICTED')),
  ADD CONSTRAINT documents_title_check CHECK (length(btrim(title)) BETWEEN 1 AND 300),
  ADD CONSTRAINT documents_tags_check CHECK (cardinality(tags) <= 20);

ALTER TABLE document_versions
  ADD CONSTRAINT document_versions_status_check CHECK (scan_status IN ('UPLOADING', 'PENDING', 'CLEAN', 'INFECTED', 'REJECTED')),
  ADD CONSTRAINT document_versions_size_check CHECK (declared_size > 0 AND declared_size <= 104857600 AND (size_bytes IS NULL OR size_bytes <= 104857600)),
  ADD CONSTRAINT document_versions_clean_check CHECK (scan_status <> 'CLEAN' OR (storage_key IS NOT NULL AND iv IS NOT NULL AND auth_tag IS NOT NULL AND sha256 IS NOT NULL));

ALTER TABLE document_acl
  ADD CONSTRAINT document_acl_target_check CHECK ((document_id IS NULL) <> (folder_id IS NULL)),
  ADD CONSTRAINT document_acl_principal_check CHECK (
    (principal_type IN ('USER', 'TEAM') AND principal_id IS NOT NULL AND principal_role IS NULL)
    OR (principal_type = 'ROLE' AND principal_role IS NOT NULL AND principal_id IS NULL)),
  ADD CONSTRAINT document_acl_permission_check CHECK (permission IN ('VIEW', 'DOWNLOAD', 'EDIT', 'MANAGE'));
CREATE UNIQUE INDEX document_acl_unique_grant ON document_acl (
  COALESCE(document_id, folder_id), principal_type, COALESCE(principal_id::text, principal_role), permission);

ALTER TABLE document_access_logs
  ADD CONSTRAINT document_access_logs_action_check CHECK (action IN ('VIEW', 'DOWNLOAD', 'UPLOAD', 'SHARE', 'DELETE', 'ACL_CHANGE', 'PASSWORD_FAIL', 'RECOVER', 'RESTORE', 'QUARANTINE', 'UPDATE'));

-- ---- Row-Level Security
DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['document_folders', 'contracts', 'documents', 'document_versions', 'document_acl', 'document_access_logs'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;

GRANT SELECT, INSERT, UPDATE, DELETE ON document_folders, document_acl TO hrvo_app;
GRANT SELECT, INSERT, UPDATE ON contracts, documents, document_versions TO hrvo_app;
REVOKE DELETE, TRUNCATE ON contracts, documents, document_versions FROM hrvo_app;
-- FR-DOC-012: the access log is append-only for the application.
GRANT SELECT, INSERT ON document_access_logs TO hrvo_app;
REVOKE UPDATE, DELETE, TRUNCATE ON document_access_logs FROM hrvo_app;
GRANT USAGE, SELECT ON SEQUENCE document_access_logs_id_seq TO hrvo_app;

-- ---- FR-DOC-009: the strongest unexpired grant for a user on a document, from the document
-- itself or any ancestor folder. 0 none, 1 VIEW, 2 DOWNLOAD, 3 EDIT, 4 MANAGE.
-- Subcontractors only get grants made to them by name or to their role, never team grants.
CREATE FUNCTION fn_acl_level(p_document UUID, p_folder UUID, p_user UUID, p_role TEXT, p_team UUID)
RETURNS INT
LANGUAGE sql STABLE AS $$
  WITH RECURSIVE chain(fid, depth) AS (
    SELECT COALESCE(p_folder, (SELECT d.folder_id FROM documents d WHERE d.id = p_document)), 0
    UNION ALL
    SELECT f.parent_id, c.depth + 1 FROM document_folders f JOIN chain c ON f.id = c.fid
    WHERE c.fid IS NOT NULL AND c.depth < 32
  )
  SELECT COALESCE(MAX(CASE a.permission WHEN 'VIEW' THEN 1 WHEN 'DOWNLOAD' THEN 2 WHEN 'EDIT' THEN 3 WHEN 'MANAGE' THEN 4 END), 0)
  FROM document_acl a
  WHERE ((p_document IS NOT NULL AND a.document_id = p_document)
         OR a.folder_id IN (SELECT fid FROM chain WHERE fid IS NOT NULL))
    AND (a.expires_at IS NULL OR a.expires_at > now())
    AND ((a.principal_type = 'USER' AND a.principal_id = p_user)
      OR (a.principal_type = 'ROLE' AND a.principal_role = p_role)
      OR (a.principal_type = 'TEAM' AND p_role <> 'SUBCONTRACTOR' AND p_team IS NOT NULL AND a.principal_id = p_team));
$$;
GRANT EXECUTE ON FUNCTION fn_acl_level(UUID, UUID, UUID, TEXT, UUID) TO hrvo_app;

-- Scheduled document jobs list tenants (ids only), like the other jobs.
CREATE FUNCTION fn_list_orgs_with_documents()
RETURNS TABLE (id UUID, timezone VARCHAR)
SECURITY DEFINER
SET search_path = public
LANGUAGE sql STABLE AS $$
  SELECT o.id, o.timezone FROM organizations o WHERE EXISTS (SELECT 1 FROM documents d WHERE d.org_id = o.id) ORDER BY o.id;
$$;
REVOKE ALL ON FUNCTION fn_list_orgs_with_documents() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_list_orgs_with_documents() TO hrvo_app;
